package main

import (
	"net/http/httptest"
	"testing"
)

func TestHello(t *testing.T) {
	req := httptest.NewRequest("GET", "/hello?name=Ada", nil)
	rec := httptest.NewRecorder()
	hello(rec, req)
	if got, want := rec.Body.String(), "Hello, Ada"; got != want {
		t.Errorf("got %q, want %q", got, want)
	}
}
